//! The committed CC0 city-coordinate gazetteer (Wikidata P625), embedded at compile
//! time. Generated by `cargo xtask iptv-gazetteer`; the server never queries
//! Wikidata at runtime.

use std::collections::HashMap;

/// The embedded TSV: `code<TAB>lat<TAB>lon` per line, `#` comments.
static GAZETTEER_TSV: &str = include_str!("../../assets/iptv-org-gazetteer.tsv");

/// City code → `(lat, lon)`.
#[derive(Debug, Clone, Default)]
pub struct Gazetteer {
    cities: HashMap<String, (f64, f64)>,
}

impl Gazetteer {
    /// The embedded gazetteer.
    #[must_use]
    pub fn embedded() -> Self {
        Self::parse(GAZETTEER_TSV)
    }

    /// Parse a TSV document; malformed lines are skipped.
    #[must_use]
    pub fn parse(tsv: &str) -> Self {
        let mut cities = HashMap::new();
        for line in tsv.lines() {
            if line.starts_with('#') || line.trim().is_empty() {
                continue;
            }
            let mut it = line.split('\t');
            let (Some(code), Some(lat), Some(lon)) = (it.next(), it.next(), it.next()) else {
                continue;
            };
            if let (Ok(lat), Ok(lon)) = (lat.parse::<f64>(), lon.parse::<f64>()) {
                cities.insert(code.to_owned(), (lat, lon));
            }
        }
        Self { cities }
    }

    /// Coordinates of a city code.
    #[must_use]
    pub fn get(&self, code: &str) -> Option<(f64, f64)> {
        self.cities.get(code).copied()
    }

    /// Number of cities with coordinates.
    #[must_use]
    pub fn len(&self) -> usize {
        self.cities.len()
    }

    /// Whether the gazetteer is empty.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.cities.is_empty()
    }
}

#[cfg(test)]
mod tests {
    use super::Gazetteer;

    #[test]
    fn embedded_gazetteer_has_wichita() {
        let g = Gazetteer::embedded();
        assert!(g.len() > 1500, "embedded gazetteer too small: {}", g.len());
        let (lat, lon) = g.get("USICT").expect("Wichita");
        assert!((lat - 37.69).abs() < 0.1 && (lon + 97.34).abs() < 0.1);
    }

    #[test]
    fn malformed_lines_are_skipped() {
        let g = Gazetteer::parse("# c\nAA\t1.0\t2.0\nbad\nBB\tx\t3\n");
        assert_eq!(g.len(), 1);
    }
}
